# AUTO-GENERATED by Claude Code
# Purpose: tests for ds.util.df.to_df: pydantic models as a polars DataFrame whose column
#          types come from the model's fields (dates, nested models, lists, empty lists,
#          all-None columns, enums) and what it refuses.
# Usage: uv run pytest tests/ds/util/test_df.py
# ---------------------------------------------------------------------------
from __future__ import annotations

import datetime as dt
import enum

import polars as pl
import pytest
from ds.util.df import to_df
from pydantic import BaseModel, computed_field


class DailyClose(BaseModel, frozen=True):
    date: dt.date
    close: float


class Side(enum.Enum):
    WIN = "win"
    LOSS = "loss"


class Player(BaseModel):
    tag: str
    seed: int | None = None


class Game(BaseModel):
    player: Player
    chars: list[str]
    side: Side
    played_at: dt.datetime | None = None
    note: str | None = None

    @computed_field
    @property
    def n_chars(self) -> int:
        return len(self.chars)


def test_columns_are_typed_from_the_fields() -> None:
    frame = to_df(
        [DailyClose(date=dt.date(2025, 11, 17), close=267), DailyClose(date=dt.date(2025, 11, 18), close=1.5)]
    )
    assert frame.schema == {"date": pl.Date, "close": pl.Float64}
    assert frame["date"][0] == dt.date(2025, 11, 17)
    assert frame.height == 2


def test_one_model_is_one_row() -> None:
    assert to_df(DailyClose(date=dt.date(2025, 11, 17), close=1.0)).shape == (1, 2)


def test_nested_models_lists_enums_and_computed_fields() -> None:
    frame = to_df([Game(player=Player(tag="MkLeo"), chars=["Joker", "Byleth"], side=Side.WIN)])
    assert frame.schema["player"] == pl.Struct({"tag": pl.String, "seed": pl.Int64})
    assert frame.schema["chars"] == pl.List(pl.String)
    assert frame["side"][0] == "win"  # an enum is its value
    assert frame.schema["n_chars"] == pl.Int64
    # columns of only None still have the field's type
    assert frame.schema["note"] == pl.String
    assert frame.schema["played_at"] == pl.Datetime("us")
    assert frame.columns == ["player", "chars", "side", "played_at", "note", "n_chars"]


def test_a_time_zone_is_kept() -> None:
    at = dt.datetime(2026, 1, 1, 12, tzinfo=dt.UTC)
    frame = to_df([Game(player=Player(tag="a"), chars=[], side=Side.LOSS, played_at=at)])
    assert frame["played_at"][0] == at


def test_an_empty_list_is_typed_when_the_class_is_given() -> None:
    assert to_df([]).shape == (0, 0)
    assert to_df([], DailyClose).schema == {"date": pl.Date, "close": pl.Float64}


@pytest.mark.parametrize("rows", [[1, 2], [DailyClose(date=dt.date(2025, 1, 1), close=1.0), Player(tag="a")]])
def test_only_models_of_one_class(rows: list[object]) -> None:
    with pytest.raises(TypeError, match="one class"):
        to_df(rows)
